import sailpoint.tools.Util;
  import java.text.SimpleDateFormat;
  import java.util.Date;

  import org.apache.log4j.Logger;

  Logger log = Logger.getLogger("iiq.alpha.Alpha-Rule-Set-lastAccessDate");
  log.debug("Alpha-Rule-Set-lastAccessDate STARTS");

  String lastAccessDate = null;
  if(null != link)
  {
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    String applicationName = link.getApplicationName();
    log.debug("applicationName:"+applicationName);
    switch(applicationName) 
    {  
      case "Alpha - Active Directory": 
      log.debug("case Alpha - Active Directory"); 
      if(Util.isNotNullOrEmpty(link.getAttribute("lastLogonTimestamp")))
      {
        //convert AD Long type to date type
        long lastLogonTimestamp = Long.parseLong(link.getAttribute("lastLogonTimestamp"));
        long offset = 11644473600000L;
        log.debug("lastLogonTimestamp:"+lastLogonTimestamp);
        Date date=new Date((lastLogonTimestamp/10000)-offset);

        lastAccessDate = sdf.format(date);
      }
      break;
      
      case "HRSoft": 
      log.debug("Case HRSoft");
      if(Util.isNotNullOrEmpty(link.getAttribute("lastAccessDate")))
      {
        String lastAcDate = link.getAttribute("lastAccessDate");
        SimpleDateFormat df = new SimpleDateFormat("yyyy-MM-dd");
        Date date = df.parse(lastAcDate);
        lastAccessDate = sdf.format(date);
      }
      break;


      default: 
      log.debug("No last modified date in the application schema");
    }
    return lastAccessDate;
  }
